-- ---------------------------------------------------------------------------------------
-- 0040 — Container loading (Module 12). ADDITIVE and tightening only; 0001–0039 are not edited.
--
--   1. Permanent internal reference is generated by the server (T26-001, T26-002 ...). A loader
--      can no longer insert t_ref. The counter starts after the highest existing sequence for the year.
--   2. The container row is written only by RPCs. Table privileges are revoked from clients, and
--      loaders read only a loader-safe column set. Consignee, shipping, invoice, payment and
--      closing columns are not granted to the loader at all.
--   3. Container evidence is accepted only while the container is loading. The check is in the
--      database (trigger), so a direct upload cannot add a photo after the loading is finished.
--   4. Official container number: ISO-style format (4 letters + 7 digits), unique, confirmed only
--      after the number photo is attached.
--   5. Loader RPCs: open (idempotent), list, get, confirm number, finish loading (transactional,
--      requires evidence, idempotent).
-- ---------------------------------------------------------------------------------------

alter table public.container_jobs add column client_request_id uuid;
create unique index container_jobs_client_request_key on public.container_jobs (client_request_id) where client_request_id is not null;

alter table public.container_jobs add constraint container_jobs_number_format_chk
  check (container_number is null or container_number ~ '^[A-Z]{4}[0-9]{7}$');

-- ---------------------------------------------------------------------------------------
-- 1. Server-generated permanent reference
-- ---------------------------------------------------------------------------------------
create table public.container_ref_counters (
  year_yy  int primary key check (year_yy between 0 and 99),
  next_seq int not null check (next_seq >= 1)
);
alter table public.container_ref_counters enable row level security;  -- no policies: RPC use only

create or replace function public._container_next_ref()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_yy int := (extract(year from public._scrap_business_date())::int) % 100;
  v_seq int;
begin
  -- Start the year's counter after the highest existing sequence (existing refs are never reused).
  insert into public.container_ref_counters (year_yy, next_seq)
  values (v_yy, coalesce((
            select max(substring(t_ref from '^T' || lpad(v_yy::text, 2, '0') || '-([0-9]{3})$')::int)
              from public.container_jobs
             where t_ref ~ ('^T' || lpad(v_yy::text, 2, '0') || '-[0-9]{3}$')), 0) + 1)
  on conflict (year_yy) do nothing;
  select next_seq into v_seq from public.container_ref_counters where year_yy = v_yy for update;
  update public.container_ref_counters set next_seq = next_seq + 1 where year_yy = v_yy;
  return 'T' || lpad(v_yy::text, 2, '0') || '-' || lpad(v_seq::text, 3, '0');
end;
$$;
revoke execute on function public._container_next_ref() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------
-- 2. Access: the container row is written only by RPCs; loaders read only safe columns
-- ---------------------------------------------------------------------------------------
drop policy if exists container_jobs_domain_write on public.container_jobs;
drop policy if exists container_jobs_domain_read on public.container_jobs;
revoke all on public.container_jobs from authenticated;
grant select (id, t_ref, container_number, number_confirmed, status, started_at, finished_at,
              loading_list_confirmed, created_at, last_update_at)
  on public.container_jobs to authenticated;
create policy container_jobs_staff_read on public.container_jobs
  for select using (public.is_container_staff());

-- Loader-safe projection. security_invoker: the caller's column grants and RLS apply.
create or replace view public.container_loader_v with (security_invoker = true) as
select c.id,
       c.t_ref,
       c.container_number,
       c.number_confirmed,
       c.status,
       c.started_at,
       c.finished_at,
       c.loading_list_confirmed,
       c.created_at,
       c.last_update_at,
       (select count(*)::int from public.media_assets m where m.owner_type = 'container' and m.owner_id = c.id
          and m.role = 'number_photo' and m.variant = 'original' and m.status = 'ready') as number_photos,
       (select count(*)::int from public.media_assets m where m.owner_type = 'container' and m.owner_id = c.id
          and m.role = 'loading_photo' and m.variant = 'original' and m.status = 'ready') as loading_photos,
       (select count(*)::int from public.media_assets m where m.owner_type = 'container' and m.owner_id = c.id
          and m.role = 'final_list' and m.variant = 'original' and m.status = 'ready') as final_list_photos
  from public.container_jobs c;
grant select on public.container_loader_v to authenticated;
revoke all on public.container_loader_v from anon;

-- ---------------------------------------------------------------------------------------
-- 3. Evidence only while loading (database-enforced for every writer, including direct uploads)
-- ---------------------------------------------------------------------------------------
create or replace function public._container_media_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
begin
  if new.owner_type <> 'container' then
    return new;
  end if;
  if new.role not in ('number_photo', 'loading_photo', 'final_list') then
    raise exception 'unknown container photo role' using errcode = '22023';
  end if;
  if public.is_export_authorized() then
    return new;
  end if;
  select status into v_status from public.container_jobs where id = new.owner_id;
  if v_status is distinct from 'loading' then
    raise exception 'this container is no longer loading; evidence cannot be added' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
revoke execute on function public._container_media_guard() from public, anon, authenticated;
create trigger media_assets_container_guard before insert on public.media_assets
  for each row execute function public._container_media_guard();

-- ---------------------------------------------------------------------------------------
-- 4. Helpers
-- ---------------------------------------------------------------------------------------
create or replace function public._container_require_staff()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '28000';
  end if;
  if not public.is_container_staff() then
    raise exception 'forbidden: a container role is required' using errcode = '42501';
  end if;
end;
$$;
revoke execute on function public._container_require_staff() from public, anon, authenticated;

create or replace function public._container_event(p_container_id uuid, p_action text, p_note text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
begin
  select name into v_name from public.profiles where id = auth.uid();
  insert into public.container_events (container_id, actor_id, actor_name, action, note)
  values (p_container_id, auth.uid(), coalesce(v_name, 'unknown'), p_action, coalesce(p_note, ''));
  perform public.write_audit_log('container.' || p_action, 'container', p_container_id, p_note, '{}'::jsonb, null, null);
end;
$$;
revoke execute on function public._container_event(uuid, text, text) from public, anon, authenticated;

create or replace function public._container_loader_row(p_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select to_jsonb(v) from public.container_loader_v v where v.id = p_id;
$$;
revoke execute on function public._container_loader_row(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------
-- 5. Loader RPCs
-- ---------------------------------------------------------------------------------------

-- Start a container. The permanent reference is generated here; the request id makes a retry safe.
create or replace function public.container_loader_open(p_client_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_ref text;
begin
  perform public._container_require_staff();
  if p_client_request_id is null then
    raise exception 'a request id is required' using errcode = '22023';
  end if;
  select id into v_id from public.container_jobs where client_request_id = p_client_request_id;
  if v_id is not null then
    return public._container_loader_row(v_id);  -- replay
  end if;
  v_ref := public._container_next_ref();
  insert into public.container_jobs (t_ref, status, started_at, created_by, last_update_at, client_request_id)
  values (v_ref, 'loading', now(), auth.uid(), now(), p_client_request_id)
  returning id into v_id;
  perform public._container_event(v_id, 'opened', 'Container ' || v_ref || ' opened for loading');
  return public._container_loader_row(v_id);
end;
$$;

-- Lists are keyset-paged. 'open' = still loading; 'ready' = loading finished; 'all'.
create or replace function public.container_loader_list(
  p_status         text default 'open',
  p_limit          int default 25,
  p_before_created timestamptz default null,
  p_before_id      uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_rows jsonb;
  v_more boolean;
begin
  perform public._container_require_staff();
  if p_status not in ('open', 'ready', 'all') then
    raise exception 'unknown list' using errcode = '22023';
  end if;
  with page as (
    select v.* from public.container_loader_v v
     where (p_status = 'all'
            or (p_status = 'open' and v.status = 'loading')
            or (p_status = 'ready' and v.status <> 'loading'))
       and (p_before_created is null or (v.created_at, v.id) < (p_before_created, p_before_id))
     order by v.created_at desc, v.id desc
     limit v_limit + 1
  )
  select coalesce(jsonb_agg((to_jsonb(x) - 'rn') order by x.created_at desc, x.id desc) filter (where x.rn <= v_limit), '[]'::jsonb),
         coalesce(bool_or(x.rn > v_limit), false)
    into v_rows, v_more
    from (select p.*, row_number() over (order by p.created_at desc, p.id desc) as rn from page p) x;
  return jsonb_build_object('rows', v_rows, 'has_more', v_more);
end;
$$;

create or replace function public.container_loader_get(p_container_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row jsonb;
begin
  perform public._container_require_staff();
  v_row := public._container_loader_row(p_container_id);
  if v_row is null then
    raise exception 'container not found' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'container', v_row,
    'photos', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'role', m.role, 'created_at', m.created_at) order by m.created_at)
                          from public.media_assets m
                         where m.owner_type = 'container' and m.owner_id = p_container_id
                           and m.variant = 'original' and m.status = 'ready'), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_build_object('action', e.action, 'actor_name', e.actor_name, 'note', e.note, 'created_at', e.created_at) order by e.created_at desc)
                          from (select * from public.container_events where container_id = p_container_id order by created_at desc limit 50) e), '[]'::jsonb)
  );
end;
$$;

-- Official container number: must match the format, be unique, and be confirmed only after the
-- number photo has been attached. Repeating the same confirmation is a no-op.
create or replace function public.container_loader_confirm_number(p_container_id uuid, p_number text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.container_jobs%rowtype;
  v_number text := upper(btrim(coalesce(p_number, '')));
begin
  perform public._container_require_staff();
  select * into c from public.container_jobs where id = p_container_id for update;
  if not found then
    raise exception 'container not found' using errcode = '22023';
  end if;
  if c.status <> 'loading' then
    raise exception 'this container is no longer loading' using errcode = 'P0001';
  end if;
  if v_number !~ '^[A-Z]{4}[0-9]{7}$' then
    raise exception 'the container number must be 4 letters and 7 digits, for example MSCU1234567' using errcode = '22023';
  end if;
  if c.number_confirmed and c.container_number = v_number then
    return public._container_loader_row(p_container_id);  -- replay
  end if;
  if not exists (select 1 from public.media_assets m where m.owner_type = 'container' and m.owner_id = p_container_id
                    and m.role = 'number_photo' and m.variant = 'original' and m.status = 'ready') then
    raise exception 'take the container number photo before confirming the number' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.container_jobs where container_number = v_number and id <> p_container_id) then
    raise exception 'that container number is already used by another container' using errcode = '22023';
  end if;
  update public.container_jobs
     set container_number = v_number, number_confirmed = true, last_update_at = now()
   where id = p_container_id;
  perform public._container_event(p_container_id, 'number_confirmed', 'Container number confirmed');
  return public._container_loader_row(p_container_id);
end;
$$;

-- Finish loading. Server-authoritative: the container moves to ready_for_invoice only when the
-- number is confirmed and both loading photos and the final loading list exist. Double finish is safe.
create or replace function public.container_loader_finish(p_container_id uuid, p_client_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.container_jobs%rowtype;
begin
  perform public._container_require_staff();
  select * into c from public.container_jobs where id = p_container_id for update;
  if not found then
    raise exception 'container not found' using errcode = '22023';
  end if;
  if c.status <> 'loading' then
    return public._container_loader_row(p_container_id);  -- already finished: replay, nothing changes
  end if;
  if not c.number_confirmed or c.container_number is null then
    raise exception 'confirm the container number before finishing loading' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.media_assets m where m.owner_type = 'container' and m.owner_id = p_container_id
                    and m.role = 'loading_photo' and m.variant = 'original' and m.status = 'ready') then
    raise exception 'add at least one loading photo before finishing' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.media_assets m where m.owner_type = 'container' and m.owner_id = p_container_id
                    and m.role = 'final_list' and m.variant = 'original' and m.status = 'ready') then
    raise exception 'add the final loading list photo before finishing' using errcode = 'P0001';
  end if;
  update public.container_jobs
     set status = 'ready_for_invoice', finished_at = now(), loading_list_confirmed = true, last_update_at = now()
   where id = p_container_id;
  perform public._container_event(p_container_id, 'loading_finished', 'Loading finished; ready for invoice');
  return public._container_loader_row(p_container_id);
end;
$$;

do $$
declare
  fn text;
begin
  foreach fn in array array[
    'container_loader_open(uuid)', 'container_loader_list(text,int,timestamptz,uuid)',
    'container_loader_get(uuid)', 'container_loader_confirm_number(uuid,text)', 'container_loader_finish(uuid,uuid)'
  ] loop
    execute format('revoke execute on function public.%s from public, anon', fn);
    execute format('grant execute on function public.%s to authenticated', fn);
  end loop;
end $$;
